// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract PairDataUltraSafe {
    struct PairInfo {
        address pairAddress;
        address token0;
        address token1;
        uint8 decimals0;
        uint8 decimals1;
        uint256 pooled0;
        uint256 pooled1;
    }

    // --- function selectors (gas optimized)
    bytes4 private constant TOKEN0 = 0x0dfe1681;
    bytes4 private constant TOKEN1 = 0xd21220a7;
    bytes4 private constant DECIMALS = 0x313ce567;
    bytes4 private constant BALANCE_OF = 0x70a08231;
    bytes4 private constant GET_RESERVES = 0x0902f1ac;

    function getPairInfo(address[] memory pairAddresses, bool[] memory isV3)
        external
        view
        returns (PairInfo[] memory)
    {
        require(pairAddresses.length == isV3.length, "Length mismatch");

        PairInfo[] memory temp = new PairInfo[](pairAddresses.length);
        uint256 validCount = 0;

        for (uint256 i = 0; i < pairAddresses.length; i++) {
            address pairAddr = pairAddresses[i];

            address t0;
            address t1;

            // --- token0()
            {
                (bool success, bytes memory data) = pairAddr.staticcall(
                    abi.encodeWithSelector(TOKEN0)
                );
                if (!success || data.length < 32) continue;
                t0 = abi.decode(data, (address));
            }

            // --- token1()
            {
                (bool success, bytes memory data) = pairAddr.staticcall(
                    abi.encodeWithSelector(TOKEN1)
                );
                if (!success || data.length < 32) continue;
                t1 = abi.decode(data, (address));
            }

            uint8 d0 = 18;
            uint8 d1 = 18;

            // --- decimals0()
            {
                (bool success, bytes memory data) = t0.staticcall(
                    abi.encodeWithSelector(DECIMALS)
                );
                if (success && data.length >= 32) {
                    d0 = abi.decode(data, (uint8));
                }
            }

            // --- decimals1()
            {
                (bool success, bytes memory data) = t1.staticcall(
                    abi.encodeWithSelector(DECIMALS)
                );
                if (success && data.length >= 32) {
                    d1 = abi.decode(data, (uint8));
                }
            }

            uint256 pooled0 = 0;
            uint256 pooled1 = 0;

            if (!isV3[i]) {
                // --- V2: getReserves()
                (bool success, bytes memory data) = pairAddr.staticcall(
                    abi.encodeWithSelector(GET_RESERVES)
                );

                if (!success || data.length < 96) continue;

                (uint112 r0, uint112 r1, ) = abi.decode(
                    data,
                    (uint112, uint112, uint32)
                );

                pooled0 = uint256(r0);
                pooled1 = uint256(r1);
            } else {
                // --- V3: balanceOf fallback

                // token0 balance
                {
                    (bool success, bytes memory data) = t0.staticcall(
                        abi.encodeWithSelector(BALANCE_OF, pairAddr)
                    );
                    if (success && data.length >= 32) {
                        pooled0 = abi.decode(data, (uint256));
                    }
                }

                // token1 balance
                {
                    (bool success, bytes memory data) = t1.staticcall(
                        abi.encodeWithSelector(BALANCE_OF, pairAddr)
                    );
                    if (success && data.length >= 32) {
                        pooled1 = abi.decode(data, (uint256));
                    }
                }
            }

            temp[validCount] = PairInfo({
                pairAddress: pairAddr,
                token0: t0,
                token1: t1,
                decimals0: d0,
                decimals1: d1,
                pooled0: pooled0,
                pooled1: pooled1
            });

            validCount++;
        }

        PairInfo[] memory result = new PairInfo[](validCount);
        for (uint256 j = 0; j < validCount; j++) {
            result[j] = temp[j];
        }

        return result;
    }
}
